// === Tab: Domino ===
class Domino {
	constructor(ang, r, val1, val2, dim, num, type) {
		this.ang = ang;
		this.r = r;
		this.val = [val1, val2];
		this.dim = dim;
		this.num = num;
		this.type = type;
	}
	show() {
		push();
		rotate(this.ang);
		translate(0, this.r);
		fill(0);
		rect(0, 0, this.dim / 2, this.dim / 1.02, this.dim / 12);
		stroke(190);
		strokeWeight(this.dim / 80);
		line(-this.dim / 4.5, 0, this.dim / 4.5, 0);
		noStroke();
		fill(255);
		if (this.num == hour() % 12 && this.type == 'hours') fill(hc);
		if (this.num == minute() && this.type == 'seconds') fill(mc);
		if (this.num == second() && this.type == 'seconds') fill(sc);
		for (let k of [-1, 1]) {
			let index = int((k + 1) / 2);
			push();
			translate(0, k * this.dim / 4);
			for (let i = 0; i < 3; i++) {
				let y = (-1 + i) * this.dim / 8;
				for (let j = 0; j < 3; j++) {
					if (patterns[this.val[(k + 1) / 2]][i].charAt(j) == '1') {
						let x = (-1 + j) * this.dim / 8;
						ellipse(x, y, this.dim / 10, this.dim / 10);
					}
				}
			}
			pop();
		}
		pop();
	}
}

// === Tab: mySketch ===
// For the #WCCChallenge, theme: "Dominoes"
// I tested a few different ways of representing the numbers on the clockface before settling on this one, 
// which required the invention of dominos that don't exist IRL, with up to 9 dots on a side!
// The hour values are to be read as the sum of the dots on the two domino sides: e.g. 12 is 6|6, 11 is 6|5, etc.
// For minutes and seconds, each domino side represents a single digit of the value: e.g. 12 is 1|2, not 6|6.

let patterns = [
	['000', '000', '000'],
	['000', '010', '000'],
	['100', '000', '001'],
	['100', '010', '001'],
	['101', '000', '101'],
	['101', '010', '101'],
	['101', '101', '101'],
	['101', '111', '101'],
	['111', '101', '111'],
	['111', '111', '111'],
];
let dominos = [];
let zoom, tzoom;
let pos, tpos;
let hc, mc, sc;

function setup() {
	createCanvas(windowHeight * 0.95, windowHeight * 0.95);
	angleMode(DEGREES);
	rectMode(CENTER);
	let v1 = 0;
	let v2 = 0;
	for (let h = 1; h <= 12; h++) {
		let a = h * 30;
		if (h < 7) {
			v1 = 0;
			v2 = h;
		} else {
			v1 = 6;
			v2 = h - 6;
		}
		let r = -height / 2 + height / 14;
		let d = new Domino(a, r, v1, v2, height / 8, h, 'hours');
		dominos.push(d);
	}
	for (let s = 0; s < 60; s++) {
		let a = s * 6;
		let r = -height / 2 + height / 6;
		let v1 = floor(s / 10);
		let v2 = s % 10;
		let d = new Domino(a, r, v1, v2, height / 16, s, 'seconds');
		dominos.push(d);
	}
	zoom = 0.25;
	tzoom = 0.95;
	pos = createVector(0, 0);
	tpos = createVector(0, 0);
	hc = 'navy';
	mc = 'blue'
	sc = 'dodgerblue';
}

function draw() {
	background(10);
	noStroke();
	translate(width / 2, height / 2);
	translate(pos)
	if(frameCount>60) zoom = lerp(zoom, tzoom, 0.1);
	let ang = 90 + second() * 6;
	let r = map(zoom, 1, 2, 0, 3 * height / 4, true);
	tpos.x = cos(ang) * r;
	tpos.y = sin(ang) * r;
	pos.lerp(tpos, 0.1);
	scale(zoom);
	noFill();
	stroke('white');
	strokeWeight(1);
	ellipse(0, 0, height * 1.02);
	fill(30);
	ellipse(0, 0, height);
	noStroke();
	for (let d of dominos) {
		d.show();
	}
	let s = second();
	let m = minute();
	let h = hour();
	let mo = month();
	let da = day();
	let yr = year();
	if (h > 12) h -= 12;
	drawClock(h, m, s, mo, da);
}

function drawClock(h, m, s, mo, da) {
	strokeCap(SQUARE);
	stroke(hc);
	strokeWeight(16 * height / 628);
	push();
	rotate(180 + 30 * h + m / 2);
	line(0, 0, 0, height / 5);
	pop();
	stroke(mc);
	strokeWeight(12 * height / 628);
	push();
	rotate(180 + m * 6 + s / 12);
	line(0, 0, 0, height / 4);
	pop();
	stroke(sc);
	strokeWeight(8 * height / 628);
	push();
	rotate(180 + s * 6);
	line(0, 0, 0, height / 2 - height / 5);
	fill(0);
	ellipse(0, 0, height / 50);
	pop();
}

function mouseWheel(event) {
	tzoom += event.delta / 1000;
	tzoom = constrain(tzoom, 0.95, 2);
}

